void events(void*,esp_event_base_t b,int32_t e,void*data){if(b==IP_EVENT&&e==IP_EVENT_STA_GOT_IP){connecting=false;wifi_reason=0;connected=true;reconnect_delay=1000;hello=false;return;}if(b==WIFI_EVENT&&e==WIFI_EVENT_STA_START){connected=false;hello=false;++epoch;reconnect_at=0;return;}if(b==WIFI_EVENT&&e==WIFI_EVENT_STA_DISCONNECTED){connecting=false;wifi_reason=static_cast<wifi_event_sta_disconnected_t*>(data)->reason;printf("NOTE4 WIFI_DISCONNECT %d\n",wifi_reason.load());connected=false;hello=false;++epoch;reconnect_at=esp_timer_get_time()+reconnect_delay*1000LL;reconnect_delay=std::min(reconnect_delay*2,8000u);}}
esp_err_t collect(esp_http_client_event_t*e){if(e->event_id==HTTP_EVENT_ON_DATA){auto*s=(std::string*)e->user_data;if(s->size()+e->data_len>16384)return ESP_FAIL;s->append((char*)e->data,e->data_len);}return ESP_OK;}
esp_http_client_handle_t http_handle=nullptr;
std::mutex http_mutex;
int http_status(const std::string&path,const std::string&body,std::string&out){
 if(!connected||base.rfind("https://",0)!=0||token.empty())return 0;
 std::lock_guard<std::mutex> guard(http_mutex);auto&h=http_handle;std::string url=base+path,auth="Bearer "+token;
 if(!h){esp_http_client_config_t c{};c.url=url.c_str();c.crt_bundle_attach=esp_crt_bundle_attach;c.timeout_ms=10000;c.disable_auto_redirect=true;c.event_handler=collect;c.user_data=&out;c.keep_alive_enable=true;h=esp_http_client_init(&c);}if(!h)return 0;
 esp_http_client_set_url(h,url.c_str());esp_http_client_set_user_data(h,&out);esp_http_client_set_header(h,"Authorization",auth.c_str());esp_http_client_set_method(h,body.empty()?HTTP_METHOD_GET:HTTP_METHOD_POST);esp_http_client_set_post_field(h,body.data(),body.size());if(!body.empty())esp_http_client_set_header(h,"Content-Type","application/json");
 bool ok=esp_http_client_perform(h)==ESP_OK;int status=ok?esp_http_client_get_status_code(h):0;if(!ok){esp_http_client_cleanup(h);h=nullptr;}return status;
}
bool http(const std::string&p,const std::string&b,std::string&o){int s=http_status(p,b,o);return s>=200&&s<300;}
std::string json(cJSON*j){char*s=cJSON_PrintUnformatted(j);std::string r=s?s:"{}";cJSON_free(s);cJSON_Delete(j);return r;}
SemaphoreHandle_t journal_lock(){static SemaphoreHandle_t m=xSemaphoreCreateMutex();return m;}
void bounded_append(const char*path,const std::string&line,size_t cap){struct stat st{};if(stat(path,&st)==0&&size_t(st.st_size)+line.size()+1>cap){++dropped;return;}FILE*f=fopen(path,"a");if(f){fwrite(line.data(),1,line.size(),f);fputc('\n',f);fclose(f);}else ++dropped;}
void flush(){
 auto m=journal_lock();xSemaphoreTake(m,portMAX_DELAY);FILE*check=fopen("/data/sending.jsonl","r");if(check)fclose(check);else rename("/data/receipts.jsonl","/data/sending.jsonl");xSemaphoreGive(m);
 FILE*f=fopen("/data/sending.jsonl","r");if(!f)return;FILE*rest=fopen("/data/receipt-rest.tmp","w");if(!rest){fclose(f);return;}char line[2048];bool retry=false;unsigned sent=0;
 while(fgets(line,sizeof(line),f)){if(strstr(line,"\"command_id\":\"usb-"))continue;if(retry||sent>=8){fputs(line,rest);continue;}++sent;std::string out;int status=http_status("/api/device/receipts",line,out);if(status>=200&&status<300)continue;if(status>=400&&status<500&&status!=408&&status!=429){auto j=std::string("http=")+std::to_string(status)+" receipt="+line;bounded_append("/data/rejected.jsonl",j,8192);printf("NOTE4 RECEIPT_QUARANTINED status=%d\n",status);continue;}retry=true;fputs(line,rest);}
 fclose(f);fflush(rest);fclose(rest);remove("/data/sending.jsonl");rename("/data/receipt-rest.tmp","/data/sending.jsonl");struct stat st{};if(stat("/data/sending.jsonl",&st)==0&&!st.st_size)remove("/data/sending.jsonl");
}

