bool provision(const char*s,const char*p,const char*b,const char*t,const char*d,int minutes){if(!s||strlen(s)>32||strlen(p)>63||strncmp(b,"https://",8)||strlen(b)>255||strlen(t)>512||strlen(d)>96)return false;nvs_handle_t h;if(nvs_open("net",NVS_READWRITE,&h)!=ESP_OK)return false;bool ok=nvs_set_str(h,"ssid",s)==ESP_OK&&nvs_set_str(h,"password",p)==ESP_OK&&nvs_set_str(h,"base",b)==ESP_OK&&nvs_set_str(h,"token",t)==ESP_OK&&nvs_set_str(h,"id",d)==ESP_OK&&(minutes<0||nvs_set_u32(h,"sync_min",minutes)==ESP_OK)&&nvs_commit(h)==ESP_OK;nvs_close(h);return ok;}
bool provision_enrollment(const char*b,const char*d,const char*code){if(strncmp(b,"https://",8)||strlen(b)>255||strlen(d)<1||strlen(d)>96||strlen(code)<24||strlen(code)>256)return false;char secret[65];for(unsigned i=0;i<8;++i)snprintf(secret+i*8,9,"%08lx",(unsigned long)esp_random());nvs_handle_t h;if(nvs_open("net",NVS_READWRITE,&h)!=ESP_OK)return false;bool ok=nvs_set_str(h,"base",b)==ESP_OK&&nvs_set_str(h,"id",d)==ESP_OK&&nvs_set_str(h,"enrollment",code)==ESP_OK&&nvs_set_str(h,"token",secret)==ESP_OK&&nvs_commit(h)==ESP_OK;nvs_close(h);return ok;}
void network_init(){char b[32];snprintf(b,sizeof b,"%08lx%08lx",(unsigned long)esp_random(),(unsigned long)esp_random());boot=b;nvs_handle_t h;if(nvs_open("net",NVS_READONLY,&h)==ESP_OK){base=read(h,"base");token=read(h,"token");id=read(h,"id");ssid=read(h,"ssid");password=read(h,"password");enrollment=read(h,"enrollment");uint32_t m=60;if(nvs_get_u32(h,"sync_min",&m)==ESP_OK)sync_minutes=m;nvs_close(h);}esp_netif_init();esp_event_loop_create_default();esp_netif_create_default_wifi_sta();ap_netif=esp_netif_create_default_wifi_ap();wifi_init_config_t c=WIFI_INIT_CONFIG_DEFAULT();if(esp_wifi_init(&c)!=ESP_OK)return;esp_wifi_set_storage(WIFI_STORAGE_RAM);esp_event_handler_register(WIFI_EVENT,ESP_EVENT_ANY_ID,events,nullptr);esp_event_handler_register(IP_EVENT,IP_EVENT_STA_GOT_IP,events,nullptr);wifi_config_t w{};strncpy((char*)w.sta.ssid,ssid.c_str(),32);strncpy((char*)w.sta.password,password.c_str(),64);have_ssid=!ssid.empty();esp_wifi_set_mode(WIFI_MODE_STA);esp_wifi_set_config(WIFI_IF_STA,&w);wifi_ready=true;}
